import sys

def main():
    tokens = sys.stdin.buffer.read().split()
    neg = {}
    pos = {}
    for t in tokens:
        if t[0] == 45:
            n = len(t)
            if n in neg:
                neg[n].append(t)
            else:
                neg[n] = [t]
        else:
            n = len(t)
            if n in pos:
                pos[n].append(t)
            else:
                pos[n] = [t]
    out = []
    for n in sorted(neg.keys(), reverse=True):
        b = neg[n]
        b.sort(reverse=True)
        out.append(b'\n'.join(b))
    for n in sorted(pos.keys()):
        b = pos[n]
        b.sort()
        out.append(b'\n'.join(b))
    sys.stdout.buffer.write(b'\n'.join(out) + b'\n')

if __name__ == '__main__':
    main()
